const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '石头' }
    ];
  },
  render: function (input, metrics) {
    var W = 560, H = 400;
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var ox = Math.max(0, (vw - W) / 2);
    var oy = Math.max(0, (vh - H) / 2);
    function off(cmds) {
      var out = [];
      for (var i = 0; i < cmds.length; i++) {
        var c = cmds[i];
        var d = [c[0]];
        for (var j = 1; j < c.length; j += 2) {
          d.push(c[j] + ox, c[j + 1] + oy);
        }
        out.push(d);
      }
      return out;
    }
    var ux = 0.98657;
    var uy = -0.16349;
    var ax = 230, ay = 233;
    var bx = ax - 90 * ux, by = ay - 90 * uy;
    var cx = ax + 180 * ux, cy = ay + 180 * uy;
    var lx = ax - 132 * ux, ly = ay - 132 * uy;
    var rx = ax + 224 * ux, ry = ay + 224 * uy;
    var nx = -5.232, ny = -31.57;
    var b2x = bx + nx, b2y = by + ny;
    var a2x = ax + nx, a2y = ay + ny;
    var c2x = cx + nx, c2y = cy + ny;
    var pGround = off(visualSdk.polyline([[20, 300], [540, 300]]));
    var pStone = off(visualSdk.polyline([[104, 268], [116, 256], [144, 257], [158, 276], [152, 297], [120, 300], [100, 288], [104, 268]]));
    var pLever = off(visualSdk.polyline([[lx, ly], [rx, ry]]));
    var pFulcrum = off(visualSdk.polyline([[208, 300], [ax, ay], [252, 300], [208, 300]]));
    var pResist = off(visualSdk.arrow(b2x, b2y, a2x, a2y, {}).concat(visualSdk.arrow(a2x, a2y, b2x, b2y, {})));
    var pEffort = off(visualSdk.arrow(a2x, a2y, c2x, c2y, {}).concat(visualSdk.arrow(c2x, c2y, a2x, a2y, {})));
    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: vw, height: vh },
      paths: [
        { id: 'ground', commands: pGround },
        { id: 'stone', commands: pStone },
        { id: 'lever', commands: pLever },
        { id: 'fulcrum', commands: pFulcrum },
        { id: 'resistArm', commands: pResist },
        { id: 'effortArm', commands: pEffort }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ground', fill: '#5A6B7A', stroke: { width: 3 } },
        { type: 'path', pathId: 'stone', fill: '#95A5A6', stroke: { width: 2 } },
        { type: 'path', pathId: 'lever', fill: '#A0703C', stroke: { width: 10 } },
        { type: 'path', pathId: 'fulcrum', fill: '#2C3E50', stroke: { width: 2 } },
        { type: 'path', pathId: 'resistArm', fill: '#2C3E50', stroke: { width: 2 } },
        { type: 'path', pathId: 'effortArm', fill: '#2C3E50', stroke: { width: 2 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: 260 + ox, y: 288 + oy }, hAlign: 'left', vAlign: 'middle', color: '#2C3E50' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: 180 + ox, y: 188 + oy }, hAlign: 'center', vAlign: 'bottom', color: '#2C3E50' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: 313 + ox, y: 168 + oy }, hAlign: 'center', vAlign: 'bottom', color: '#2C3E50' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: 130 + ox, y: 278 + oy }, hAlign: 'center', vAlign: 'middle', color: '#FFFFFF' }
      ] }
    };
  }
};
